+void unblockedEquivalence() {
+    Traffic reference,fast;
+    std::array<Traffic::Context,12> members;
+    for(size_t i=0;i<members.size();++i) {
+        members[i]=context(int(i+1),{100,100+int(i)*4},{1000,100});
+        reference.registerMove(members[i]);fast.registerMove(members[i]);
+    }
+    unsigned shortcuts=0,declines=0;
+    for(uint32_t tick=1;tick<=1000;++tick)for(auto& c:members) {
+        c.tick=tick;
+        if(tick<350||tick>700)++c.position.x;
+        if(tick==120)++c.controller; // Internal retry preserves mission progress.
+        if(tick==240){++c.issuedTick;c.target.z+=100;} // Replacement changes group.
+        if(tick==410){reference.cancel(c.id);fast.cancel(c.id);}
+        if(tick==720){c.blocked=2;c.obstructionFriendly=true;c.obstruction=neighbor(members.back());}
+        if(tick==760){c.blocked=0;c.obstruction.reset();}
+        if(tick==950){c.position=c.target;c.goalReached=true;}
+        auto cheap=c;cheap.free={};cheap.terrainFree={};cheap.arrivalReachable={};cheap.contactReachable={};
+        const auto expected=reference.update(c);
+        Traffic::Result actual;
+        const auto before=fast.checksum();
+        if(fast.updateUnblocked(cheap))++shortcuts;
+        else {
+            check(fast.checksum()==before,"declined shortcut changed state before a deferred adapter query");
+            ++declines;actual=fast.update(c);
+        }
+        check(expected.settled==actual.settled&&expected.detour==actual.detour&&expected.wait==actual.wait&&
+              expected.repath==actual.repath&&expected.arrivalApproach==actual.arrivalApproach&&
+              expected.followLeader==actual.followLeader&&reference.checksum()==fast.checksum(),
+              "unblocked shortcut changed traffic results or per-update state");
+    }
+    check(shortcuts>1000&&declines>100,"equivalence fixture missed fast or retained/arrival paths");
+}
+void terrainScopedRetries() {
+    // A short shoulder is free, but every forward reconnection crosses this
+    // wall. The bounded search can finish, unlike a quota-exhausted open field.
+    const auto scenario=[](int wake,bool bodyOnly,bool deferredProof) {
+        Traffic traffic;auto c=context(1,{100,100},{900,100});
+        auto peer=context(2,{102,100},{900,100});
+        c.blocked=2;c.obstructionFriendly=true;c.obstruction=neighbor(peer);
+        bool opened=false,terrainBlocked=false,localDeferred=false;
+        unsigned refused=0;
+        c.localTerrainBlocked=&terrainBlocked;c.localDeferred=&localDeferred;
+        const auto terrain=[&](Cell at){return opened||!(at.x>=103&&at.z==100);};
+        c.terrainFree=[&](Cell at){
+            const bool clear=terrain(at);
+            if(!clear) {
+                if(deferredProof&&++refused==2)localDeferred=true;
+                if(!localDeferred)terrainBlocked=true;
+            }
+            return clear;
+        };
+        c.free=[&](Cell at){return bodyOnly?at==c.position:
+            at.x>=98&&at.x<=105&&at.z>=98&&at.z<=102&&terrain(at)&&!overlaps(at,2,2,peer.position,2,2);};
+        traffic.registerMove(c);
+        for(c.tick=1;c.tick<=3;++c.tick) {
+            terrainBlocked=localDeferred=false;refused=0;traffic.update(c);
+        }
+        const auto before=traffic.stats();
+        if(bodyOnly||deferredProof) {
+            check(!before.retrySkips&&before.searches==2,
+                  "body-only or deferred terrain failure delayed a necessary retry");
+            check(deferredProof?before.deferredSearches>0:before.completeFailures==2,
+                  "retry fixture did not distinguish complete and deferred failures");
+            return;
+        }
+        check(before.completeFailures==1&&before.searches==1&&before.retrySkips==1,
+              "proved failed terrain reconnection did not retain bounded retry state");
+        // Even without a peer/context change, a newly opened route is retried
+        // by the original failure tick + 8; skipped callers do not renew it.
+        if(!wake) {
+            opened=true;bool routed=false;
+            for(c.tick=4;c.tick<=10;++c.tick) {
+                terrainBlocked=localDeferred=false;refused=0;
+                routed|=traffic.update(c).detour.has_value();
+            }
+            check(routed&&traffic.stats().searches==2,"cleared terrain did not wake the original unchanged retry");
+            return;
+        }
+        if(wake==1)++c.controller;
+        if(wake==2)c.steeringTarget->x++;
+        if(wake==3)--c.position.x;
+        if(wake==4)++c.obstruction->position.z;
+        if(wake==5)c.obstruction->steeringTarget=Cell{0,100};
